            animation: ticker 16s linear infinite;
        }

        .notice-text {
            display: flex;
            align-items: center;
            gap: 10px;

            white-space: nowrap;

            color: #fff;

            font-size: .95rem;
            font-weight: 500;

            padding: 0 20px;
        }

        .notice-text i {
            color: #ff4da6;
        }

        @keyframes ticker {
            from {
                transform: translateX(0);
            }

            to {
                transform: translateX(-50%);
            }
        }


        .telegram-floating-btn {
            position: fixed;

            right: 24px;
            bottom: 24px;

