                    #00d4ff);

            box-shadow:
                0 15px 35px rgba(0, 0, 0, .35),
                0 0 25px rgba(124, 77, 255, .5);

            transition: .25s ease;

            display: flex;
            align-items: center;
            gap: 10px;
        }

        .telegram-floating-btn:hover {
            transform:
                translateY(-4px) scale(1.04);
        }

    

        .continue-popup {
            position: fixed;
            inset: 0;

            background: rgba(0, 0, 0, .75);

            display: flex;
            justify-content: center;
            align-items: center;

            z-index: 9999;

            opacity: 0;
            visibility: hidden;

            transition: .3s ease;

            backdrop-filter: blur(8px);
        }

        .continue-popup.active {
            opacity: 1;
            visibility: visible;
        }

        .popup-box {
            width: min(420px, 90%);

            background:
                linear-gradient(145deg,
                    rgba(25, 25, 35, .96),
                    rgba(15, 15, 20, .96));

            border: 1px solid rgba(255, 255, 255, .08);

            border-radius: 24px;

            padding: 30px 24px;

            text-align: center;

            box-shadow:
                0 20px 60px rgba(0, 0, 0, .45),
                0 0 30px rgba(124, 77, 255, .25);

            animation: popupShow .35s ease;
        }

        .popup-box h2 {
            font-size: 1.6rem;
            margin-bottom: 10px;
        }

        .popup-box p {
            color: #b8c1d9;

            font-size: .95rem;
            line-height: 1.6;

            margin-bottom: 24px;
        }

        .continue-btn {
            display: inline-flex;
            justify-content: center;
            align-items: center;

            width: 100%;

            padding: 15px 20px;

            border-radius: 16px;

            text-decoration: none;

            font-weight: 700;
            font-size: 1rem;

            color: #fff;

            background:
                linear-gradient(135deg,
                    #ff512f,
                    #dd2476);

            box-shadow:
                0 10px 30px rgba(221, 36, 118, .35);

            transition: .25s ease;
        }

        .continue-btn:hover {
            transform: translateY(-3px);
        }

        @keyframes popupShow {

            from {
                transform: scale(.85);
                opacity: 0;
            }

            to {
                transform: scale(1);
                opacity: 1;
            }

        }


        @media(max-width:768px) {

            .container {
                padding: 15px;
            }

            .button-group {
                flex-direction: row;
                gap: 8px;
            }

            .folder-btn {
                font-size: .85rem;
                padding: 13px 8px;
            }

            .telegram-floating-btn {
                right: 16px;
                bottom: 16px;

                padding: 14px 18px;
                font-size: .9rem;
            }

            .notice-text {
                font-size: .85rem;
            }

        }
        
